public static void addBuffer(TFMProcessSessionID _sessionId, Common _buffer)
{
    TFMProcessSessionsDataCollected sessionData;
    sessionData.ProcessSessionID    = _sessionId;
    sessionData.RefTableName        = tableId2Name(_buffer.TableId);
    sessionData.RefRecId            = _buffer.RecId;

    sessionData.insert();
}

public static boolean SessionHasData(TFMProcessSessionID _sessionId)
{
    TFMProcessSessionsDataCollected sessionData;

    select firstonly RecId from sessionData where sessionData.ProcessSessionID == _sessionId;

    return sessionData.RecId;
}

public static Map makeDataSet(TFMProcessSessionID _sessionId)
{
    Map                 transferData = new Map(Types::String, Types::String);
    Common              data;

    TFMProcessSessionsDataCollected sessionData;

    while select sessionData where sessionData.ProcessSessionID == _sessionId
    {                    
        data = TFMProcessSessionsDataCollected::findBuffer(sessionData.RefTableName, sessionData.RefRecId);

        transferData.insert(TFMHelper::descriptionFromCommon(data), data.xml());

    }
    return transferData;

}

public static Common findBuffer(TableName _tableName, RefRecId _recId)
{
    Common      record = new DictTable(tableName2Id(_tableName)).makeRecord();

    select firstonly record where record.RecId == _recId;

    return record;
}
